package com.bank.bulk.repository;

import com.bank.bulk.model.Account;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface AccountRepository extends JpaRepository<Account, String> {

    // chunked: safe IN with a bounded batch
    @Query("select a from Account a where a.id in :ids")
    List<Account> findByIdChunk(@Param("ids") List<String> ids);

    // array join via = ANY (PostgreSQL) — one efficient query for all ids
    @Query(value = "select * from accounts a where a.id = ANY(:ids)", nativeQuery = true)
    List<Account> findByIdArray(@Param("ids") String[] ids);

    // server-side filter: ids never leave the database
    @Query(value = "select a.* from accounts a " +
                   "where a.id in (select account_id from flagged_accounts)",
           nativeQuery = true)
    List<Account> findFlagged();
}
