package com.bank.bulk.service;

import com.bank.bulk.model.Account;
import com.bank.bulk.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@Slf4j
@Service
@RequiredArgsConstructor
public class AccountLookupService {
    private final AccountRepository repo;
    private static final int CHUNK = 1000;   // safe batch size

    // Strategy 1: chunk a large id list into bounded IN queries
    @Transactional(readOnly = true)
    public List<Account> lookupChunked(List<String> ids) {
        List<Account> all = new ArrayList<>();
        for (int i = 0; i < ids.size(); i += CHUNK) {
            List<String> batch = ids.subList(i, Math.min(i + CHUNK, ids.size()));
            all.addAll(repo.findByIdChunk(batch));   // <=1000 binds per query
        }
        log.info("Chunked lookup of {} ids in {} batches", ids.size(),
                 (ids.size() + CHUNK - 1) / CHUNK);
        return all;
    }

    // Strategy 2: single array-join query, no literal-count limit
    @Transactional(readOnly = true)
    public List<Account> lookupArray(List<String> ids) {
        String[] arr = ids.toArray(new String[0]);
        List<Account> result = repo.findByIdArray(arr);  // = ANY(:ids)
        log.info("Array lookup of {} ids in one query", ids.size());
        return result;
    }

    // Strategy 3: server-side filter — ids never cross the wire
    @Transactional(readOnly = true)
    public List<Account> lookupFlagged() {
        return repo.findFlagged();
    }
}
